/* EstudaLab: question variety engine (stable across attempts). */
const quizShuffle = list => {
  const arr=[...list];
  for(let i=arr.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[arr[i],arr[j]]=[arr[j],arr[i]];}
  return arr;
};
function quizVariety(items,n,namespace,keyOf,topicOf){
  const storageKey='estudalab.quiz.variety.v3.'+namespace;
  let history=[];
  try {const saved=JSON.parse(localStorage.getItem(storageKey)||'[]');history=Array.isArray(saved)?saved.filter(x=>typeof x==='string').slice(-400):[]}catch{}
  const byId=new Map();
  for(const item of items){const id=String(keyOf(item));if(id&&!byId.has(id))byId.set(id,item)}
  const pool=[...byId.values()];
  const selected=[],picked=new Set(),topicCount=new Map();
  const lastSeen=item=>history.lastIndexOf(String(keyOf(item)));
  const topic=item=>String(topicOf(item)||'Geral');
  while(selected.length<Math.min(n,pool.length)){
    let possible=pool.filter(x=>!picked.has(String(keyOf(x))));
    const unseen=possible.filter(x=>lastSeen(x)<0);
    // No question is repeated while any unused question remains in this bank.
    if(unseen.length){possible=unseen}
    else{
      // Once the full bank has been used, bring back the oldest questions first.
      possible.sort((a,b)=>lastSeen(a)-lastSeen(b));
      possible=possible.slice(0,Math.min(possible.length,Math.max(5,(n-selected.length)*2)));
    }
    const minimum=Math.min(...possible.map(x=>topicCount.get(topic(x))||0));
    let candidates=possible.filter(x=>(topicCount.get(topic(x))||0)===minimum);
    if(!unseen.length){const oldest=Math.min(...candidates.map(lastSeen));candidates=candidates.filter(x=>lastSeen(x)===oldest)}
    const item=candidates[Math.floor(Math.random()*candidates.length)];
    const id=String(keyOf(item)),cat=topic(item);
    selected.push(item);picked.add(id);topicCount.set(cat,(topicCount.get(cat)||0)+1);
  }
  history=[...history,...selected.map(x=>String(keyOf(x)))].slice(-400);
  try{localStorage.setItem(storageKey,JSON.stringify(history))}catch{}
  return quizShuffle(selected);
}
function randomizedAnswers(original,optionsField,answerField){
  const item={...original};
  const options=original[optionsField].map((value,index)=>({value,isCorrect:index===original[answerField]}));
  const randomized=quizShuffle(options);
  item[optionsField]=randomized.map(x=>x.value);
  item[answerField]=randomized.findIndex(x=>x.isCorrect);
  return item;
}
function randomizedMath(q){
  const options=quizShuffle(q[2].map((value,index)=>({value,isCorrect:index===q[3]})));
  return [q[0],q[1],options.map(v=>v.value),options.findIndex(v=>v.isCorrect),q[4]];
}

