function home(){return `<section class="hero"><div class="hero-main"><div class="eyebrow">✳ Sua central de revisão</div><h1>Biologia sem <em>desespero.</em><br>Uma coisa de cada vez.</h1><p>Os 10 assuntos do teu caderno, explicados do zero. Macetes, flashcards, gráficos e um simulado com correção comentada.</p><div class="hero-actions"><button class="btn btn-dark" data-open="lesson/${L.find(l=>!state.done.includes(l.id))?.id||L[0].id}">✦ Continuar estudando</button><button class="btn btn-outline" data-open="exam">▶ Fazer simulado</button></div></div><div class="hero-art"><div class="blob"></div><div class="hero-ring"></div></div></section>
<div class="stats"><div class="stat"><span class="stat-icon">📖</span><div><strong>${state.done.length}/10</strong><small>Assuntos concluídos</small></div></div><div class="stat"><span class="stat-icon">🧠</span><div><strong>${Object.values(state.cards).filter(x=>x==='know').length}</strong><small>Flashcards dominados</small></div></div><div class="stat"><span class="stat-icon">🏆</span><div><strong>${state.best}%</strong><small>Melhor simulado</small></div></div></div>
<div class="section-head"><div><h2>Seu roteiro de estudos</h2><p>Comece pelos hormônios, depois avance para sistema nervoso e reprodução.</p></div><button class="text-link" data-open="flash">Praticar memória →</button></div>
<div class="lesson-grid" id="lessonGrid">${L.map(lessonCard).join('')}</div>
<div class="section-head"><div><h2>Revisão turbo</h2><p>Esses três fatos aparecem o tempo todo nas questões.</p></div></div><div class="two-col"><div class="callout"><strong>⚡ Macete dos hormônios</strong><p>FSH = folículo · LH = ovulação · TSH = tireoide · ACTH = suprarrenal · GH = crescimento · ADH = guardar água.</p></div><div class="callout"><strong>🧬 Macete da reprodução</strong><p>Fecundação = tuba uterina. Nidação = endométrio. Ovócito secundário = célula ovulada.</p></div></div>`}
function miniQuiz(l){const q=l.q;return `<section class="lesson-quiz" id="quickQuiz"><div class="mini-top">QUESTÃO DE FIXAÇÃO</div><h3>${esc(q.q)}</h3><div class="quiz-options">${q.opts.map((o,i)=>`<button type="button" class="option" data-mini="${i}"><span class="letter">${'ABCD'[i]}</span>${esc(o)}</button>`).join('')}</div><div id="miniFeedback" role="status" aria-live="polite"></div></section>`}
function lesson(id){const l=getTopic(id);if(!l)return home();miniAnswer=null;return `<div class="lesson-header"><div class="eyebrow">TRILHA DE APRENDIZADO · ${l.tag.toUpperCase()}</div><div class="lesson-top"><span class="topic-icon">${l.icon}</span><div><h1>${esc(l.title)}</h1><p>${esc(l.subtitle)} · Leitura de ${l.mins} min</p></div></div><div class="floating-tools"><button type="button" class="btn btn-ghost btn-small" data-open="home">← Voltar</button><button type="button" class="btn btn-primary btn-small" data-mark="${l.id}">${state.done.includes(l.id)?'✓ Marcado como estudado':'✓ Marcar como estudado'}</button></div></div>
<div class="lesson-layout"><div class="lesson-body"><section class="panel"><h2>Entenda para a prova</h2>${l.body}</section><section class="panel"><h2>Teste se aprendeu</h2>${miniQuiz(l)}</section><div class="panel"><div class="section-head" style="margin:0"><div><h3>Próximo passo</h3><p>Continue para a próxima aula ou revise com flashcards.</p></div></div><div class="floating-tools"><button class="btn btn-primary" data-next-lesson="${l.id}">Próxima aula →</button><button class="btn btn-ghost" data-open="flash">Treinar flashcards</button></div></div></div><aside class="lesson-aside"><div class="note"><h4>💡 Macete que salva</h4><p>${esc(l.macete)}</p></div><div class="note rose"><h4>⚠ Pegadinha comum</h4><p>${esc(l.trap)}</p></div><div class="panel" style="padding:17px"><div class="mini-top">PROGRESSO DO TÓPICO</div><p style="font-size:12px;margin:10px 0 14px">Releia os macetes, responda à questão e marque como estudado quando sentir segurança.</p><button class="btn btn-outline btn-small" data-mark="${l.id}">${state.done.includes(l.id)?'Desmarcar estudo':'✓ Concluir assunto'}</button></div></aside></div>`}
function getDeck(){return FC.map((c,i)=>({topic:c[0],q:c[1],a:c[2],id:i})).filter(c=>{
if(flashFilter==='all')return true;
if(flashFilter==='review')return state.cards[c.id]==='again';
if(flashFilter==='known')return state.cards[c.id]==='know';
if(flashFilter==='new')return !state.cards[c.id];
return c.topic===flashFilter;
})}
function flash(){return EstudaLabStudyUI.flashHTML('biologia',FC.map((c,id)=>({id,topic:getTopic(c[0])?.title||c[0],front:c[1],back:c[2]})),{label:'Biologia',legacy:id=>state.cards[id],onGrade:(id,grade)=>{state.cards[id]=['good','easy'].includes(grade)?'know':'again';save()}})}
function flipFlash(){if(!flashOrder.length)return;flashFlipped=!flashFlipped;const card=$('#flashCard');if(!card)return;card.classList.toggle('flipped',flashFlipped);card.setAttribute('aria-pressed',String(flashFlipped));card.setAttribute('aria-label',flashFlipped?'Virar cartão: ver pergunta':'Virar cartão: revelar resposta');const flip=$('#flipCard');if(flip)flip.textContent=flashFlipped?'↶ Ver pergunta':'↻ Revelar resposta';for(const key of ['#markAgain','#markKnow']){const b=$(key);if(b)b.disabled=!flashFlipped}}
function startExam(n){const selected=quizVariety(BANK,15,'bio',q=>q.id,q=>q.topic);exam={qs:selected.map(q=>randomizedAnswers(q,'opts','a')),idx:0,answers:[],finished:false};render()}
function examPage(){return EstudaLabStudyUI.quizHTML('biologia',BANK.map(q=>({id:q.id,legacyId:q.id,topic:getTopic(q.topic)?.title||q.topic,prompt:q.q,options:q.opts,answer:q.a,explanation:q.why})),{label:'Biologia',legacyNamespace:'bio',onComplete:(hits,total)=>{state.best=Math.max(state.best,Math.round(hits/total*100));save()}})}
const gauss=(x,mu,sig)=>Math.exp(-Math.pow(x-mu,2)/(2*sig*sig));
const profiles={LH:{color:'#8368da',fn:d=>7+93*gauss(d,14.2,1.05)},FSH:{color:'#4d9fd0',fn:d=>12+18*gauss(d,13.9,2)+7*gauss(d,2,3)},'Estrogênio':{color:'#ec9150',fn:d=>13+57*gauss(d,12.2,3.25)+22*gauss(d,21,3.2)},'Progesterona':{color:'#27a682',fn:d=>4+69*gauss(d,21.7,4.25)*(1/(1+Math.exp(-(d-14.5)*1.6)))} };
function chartSvg(){const W=800,H=295,l=48,r=16,t=18,b=38,pw=W-l-r,ph=H-t-b;const X=d=>l+(d-1)/27*pw,Y=y=>t+ph-y/110*ph;
const ticks=[0,25,50,75,100].map(y=>`<line x1="${l}" y1="${Y(y)}" x2="${W-r}" y2="${Y(y)}" stroke="currentColor" opacity=".12"/><text x="${l-9}" y="${Y(y)+4}" text-anchor="end" fill="currentColor" opacity=".45" font-size="11">${y}</text>`).join('');
const days=[1,7,14,21,28].map(d=>`<text x="${X(d)}" y="${H-10}" text-anchor="middle" fill="currentColor" opacity=".6" font-size="12">${d}</text>`).join('');
const lines=Object.entries(profiles).filter(([name])=>visibleSeries.has(name)).map(([name,p])=>{const pts=Array.from({length:190},(_,i)=>{let d=1+i*27/189;return `${X(d).toFixed(1)},${Y(p.fn(d)).toFixed(1)}`}).join(' ');return `<polyline points="${pts}" fill="none" stroke="${p.color}" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"/>`}).join('');
return `<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Gráfico ilustrativo dos níveis relativos de LH, FSH, estrogênio e progesterona ao longo de 28 dias">${ticks}<line x1="${X(14)}" y1="${t}" x2="${X(14)}" y2="${H-b}" stroke="#9bbfb0" stroke-dasharray="4 6"/><text x="${X(14)+8}" y="29" font-size="11" fill="currentColor" opacity=".6">Ovulação ilustrativa</text>${days}${lines}<line id="dayCursor" x1="${X(cycleDay)}" y1="${t}" x2="${X(cycleDay)}" y2="${H-b}" stroke="#133e32" stroke-width="2" stroke-dasharray="4 4"/><circle id="dayDot" cx="${X(cycleDay)}" cy="${Y(profiles.LH.fn(cycleDay))}" r="5" fill="#133e32" stroke="white" stroke-width="2"/><text x="${W-10}" y="${t+5}" fill="currentColor" opacity=".45" font-size="10" text-anchor="end">Dias</text></svg>`}
function phaseFor(d){if(d<=5)return ['Menstruação','A camada superficial do endométrio é eliminada. FSH pode começar a estimular folículos para o ciclo seguinte.'];if(d<=12)return ['Fase folicular','Folículos amadurecem e o estrogênio tende a aumentar. O endométrio começa a se reconstruir.'];if(d<=15)return ['Janela da ovulação','O pico de LH desencadeia a ovulação. O dia 14 é apenas um exemplo didático para um ciclo de 28 dias.'];if(d<=24)return ['Fase lútea','O corpo lúteo produz progesterona, favorecendo a manutenção do endométrio.'];return ['Fim da fase lútea','Se não houver gestação, o corpo lúteo regride; caem estrogênio e progesterona, aproximando a menstruação.']}
function cycle(){let [p,desc]=phaseFor(cycleDay);return `<div class="eyebrow">LABORATÓRIO INTERATIVO</div><h1 class="title-xl">Explore o ciclo menstrual.</h1><p class="subtitle">Arraste o dia e observe a mudança relativa dos hormônios. O gráfico é uma representação didática, não serve para prever ovulação individual nem como método contraceptivo.</p><div class="section-head"><div><h2>Curvas hormonais</h2><p>Ative e desative as linhas para estudar uma por vez.</p></div></div><div class="lab-layout"><div class="panel"><div class="chart-wrap" id="chart">${chartSvg()}</div><div class="legend">${Object.entries(profiles).map(([name,p])=>`<button class="${visibleSeries.has(name)?'':'inactive'}" data-series="${name}"><span class="pill-dot" style="background:${p.color}"></span>${name}</button>`).join('')}</div><div class="callout" style="margin-top:17px"><strong>Como identificar no gráfico da prova?</strong><p>LH tem pico muito alto e estreito; FSH tem pico menor; estrogênio cresce antes da ovulação; progesterona cresce depois.</p></div></div><aside class="panel"><div class="day-head"><div><div class="mini-top">DIA SIMULADO</div><div class="bigday" id="cycleNum">${cycleDay}</div></div><span class="phase" id="phaseName">${p}</span></div><input aria-label="Selecionar dia do ciclo" type="range" class="range" min="1" max="28" value="${cycleDay}" id="daySlider"><div class="small muted">Dia 1 <span style="float:right">Dia 28</span></div><div class="phase-desc" id="phaseDesc" style="margin:20px 0">${desc}</div><button class="btn btn-primary" data-open="lesson/graficos">Estudar interpretação de gráficos →</button></aside></div><div class="section-head"><div><h2>Menopausa: o padrão que cai</h2></div></div><div class="two-col"><div class="callout"><strong>↑ FSH e LH sobem</strong><p>Os ovários deixam de produzir níveis elevados de hormônios que freiam a hipófise.</p></div><div class="callout"><strong>↓ Estrogênio e progesterona caem</strong><p>Ocorre perda progressiva da atividade folicular, com fim da ovulação e da menstruação.</p></div></div>`}
function hormones(){const h=HORMONE_GAME[hIndex];return `<div class="eyebrow">JOGO DE ASSOCIAÇÃO</div><h1 class="title-xl">Batalha dos hormônios.</h1><p class="subtitle">A professora cita o nome do hormônio e você precisa saber sua ação. Aqui é exatamente esse treino, uma pergunta por vez.</p><div class="panel" style="max-width:800px;margin-top:25px"><div class="exam-head"><div><div class="mini-top">HORMÔNIO ${hIndex+1} DE ${HORMONE_GAME.length}</div><h2 style="margin:8px 0;font-size:31px">${esc(h.h)}</h2></div><span class="tag">${hScore} acertos</span></div><p>Qual é a função principal desse hormônio?</p><div class="quiz-options">${h.o.map((x,i)=>`<button class="option ${hAnswered?(i===h.a?'right':''):''}" type="button" data-hormone="${i}" ${hAnswered?'disabled':''}><span class="letter">${'ABCD'[i]}</span>${esc(x)}</button>`).join('')}</div><div id="hFeedback" aria-live="polite"></div><button id="nextHormone" class="btn btn-primary" ${!hAnswered?'disabled':''}>${hIndex===HORMONE_GAME.length-1?'Recomeçar a rodada':'Próximo hormônio →'}</button></div>`}
const REFLEX=[['🔥','Receptor','A pele detecta o estímulo nocivo, por exemplo calor intenso.'],['📩','Neurônio sensitivo','O impulso é conduzido da pele até a medula espinhal.'],['🧩','Medula espinhal','Circuitos nervosos locais integram a informação e ativam a resposta motora.'],['⚡','Neurônio motor','O sinal eferente sai da medula rumo ao músculo.'],['💪','Músculo','O músculo contrai e a mão se afasta do estímulo.']];
function reflex(){return `<div class="eyebrow">SIMULADOR DIDÁTICO</div><h1 class="title-xl">Como funciona um ato reflexo?</h1><p class="subtitle">Clique em cada etapa do arco reflexo e acompanhe o caminho do impulso nervoso.</p><div class="panel" style="margin-top:24px"><div class="steps-arc">${REFLEX.map((r,i)=>`<button class="arc-step ${i===reflexIndex?'active':''}" data-reflex="${i}"><span>${r[0]}</span>${r[1]}</button>`).join('')}</div><div class="callout" style="margin:17px 0"><strong>${reflexIndex+1}. ${REFLEX[reflexIndex][1]}</strong><p>${REFLEX[reflexIndex][2]}</p></div><div class="floating-tools"><button class="btn btn-ghost" data-reflex-nav="prev" ${reflexIndex===0?'disabled':''}>← Anterior</button><button class="btn btn-primary" data-reflex-nav="next">${reflexIndex===4?'Recomeçar':'Próxima etapa →'}</button></div></div><div class="section-head"><div><h2>Não confunda</h2></div></div><div class="callout"><strong>O reflexo não precisa esperar a percepção consciente</strong><p>A medula pode organizar a resposta rápida enquanto informações também chegam ao cérebro.</p></div>`}
const ESSAYS=[
['Explique o caminho hormonal do eixo hipotálamo–hipófise–tireoide e o papel do feedback negativo.','O hipotálamo libera TRH, que estimula a hipófise anterior a secretar TSH. O TSH estimula a tireoide a liberar T3/T4. Quando T3/T4 estão elevados, inibem TRH/TSH por feedback negativo.'],
['Uma pessoa ficou desidratada após exercícios. O que acontece com o ADH e a urina?','O ADH tende a aumentar, elevando a reabsorção de água nos rins. O volume de urina diminui e ela tende a ficar mais concentrada.'],
['Como identificar o LH num gráfico do ciclo e qual seu papel na ovulação?','O LH apresenta pico alto e estreito próximo da ovulação. Esse pico desencadeia a liberação do ovócito secundário.'],
['Diferencie ovócito primário e secundário quanto à meiose.','O ovócito primário (2n) fica parado na prófase I. Após completar a meiose I, surge o ovócito secundário (n), ovulado e parado na metáfase II.'],
['Diferencie fecundação e nidação, informando onde ocorrem.','Fecundação é a união dos gametas e ocorre geralmente na tuba uterina. Nidação é a implantação do blastocisto no endométrio do útero, dias depois.']
];
function essayPage(){return `<div class="eyebrow">TREINO DE RESPOSTA ABERTA</div><h1 class="title-xl">Discursiva com 5 itens.</h1><p class="subtitle">Nas tuas anotações aparece uma discursiva com cinco itens. Treine escrevendo com tuas palavras e abra a resposta-modelo só depois. As perguntas abaixo são simuladas, não são a prova real.</p><div class="panel" style="margin-top:23px">${ESSAYS.map((x,i)=>`<section style="padding:12px 0 22px;${i?'border-top:1px solid var(--stroke);':''}"><div class="mini-top">ITEM ${'ABCDE'[i]}</div><h3 style="margin:9px 0">${esc(x[0])}</h3><textarea aria-label="Sua resposta do item ${'ABCDE'[i]}" style="width:100%;min-height:105px;background:var(--panel);color:var(--ink);border:1px solid var(--stroke);border-radius:12px;padding:13px;resize:vertical;line-height:1.5" placeholder="Escreva sua resposta sem consultar..." ></textarea><details style="margin-top:12px;border:1px solid var(--stroke);padding:12px 14px;border-radius:12px"><summary style="cursor:pointer;font-size:12px;font-weight:800;color:var(--green)">Ver resposta-modelo e comparar</summary><p style="font-size:13px;color:var(--ink2)">${esc(x[1])}</p></details></section>`).join('')}</div><div class="callout" style="margin-top:15px"><strong>Macete para discursivas</strong><p>Não basta escrever o nome do hormônio. Responde sempre em três partes: causa → mecanismo → consequência. Exemplo: desidratação → sobe ADH → menos urina.</p></div>`}
function render(){curPage=parseHash();let title='',page='';if(curPage==='home'){title='Visão geral';page=home()}else if(curPage.startsWith('lesson/')){let id=curPage.split('/')[1],l=getTopic(id);title=l?.title||'Visão geral';page=lesson(id)}else if(curPage==='aulas'){title='Aulas';page='<div class="section-head"><div><h1>Seu roteiro de Biologia</h1><p>Escolha uma aula para continuar.</p></div></div><label for="searchInput">Buscar aulas</label><input id="searchInput" type="search" placeholder="Hormônios, reprodução, sistema nervoso…"><div class="lesson-grid" id="lessonGrid">'+L.map(lessonCard).join('')+'</div>'}else if(curPage==='flash'){title='Flashcards';page=flash()}else if(curPage==='exam'){title='Simulado';page=examPage()}else if(curPage==='cycle'){title='Ciclo menstrual';page=cycle()}else if(curPage==='hormones'){title='Hormônios';page=hormones()}else if(curPage==='reflex'){title='Ato reflexo';page=reflex()}else if(curPage==='essay'){title='Questão discursiva';page=essayPage()}else{curPage='home';title='Visão geral';page=home()}
$('#content').innerHTML=page;document.title=`${title} · EstudaLab`;shell.setRoute(curPage.startsWith('lesson/')?'aulas':curPage,title);updateGlobal()}
function navigateNav(s){if(s.startsWith('lesson/'))miniAnswer=null;navTo(s)}
function flashChange(delta){if(!flashOrder.length)return;flashIdx=(flashIdx+delta+flashOrder.length)%flashOrder.length;flashFlipped=false;render()}
function setFlashFilter(filter){flashFilter=filter;flashOrder=[];flashIdx=0;flashFlipped=false;render()}
function markFlash(v){if(!flashFlipped||!flashOrder.length)return;state.cards[flashOrder[flashIdx]]=v;save();flashChange(1)}
function answerMini(btn){if(miniAnswer!==null)return;let l=getTopic(curPage.split('/')[1]);if(!l)return;let n=Number(btn.dataset.mini);miniAnswer=n;$$('[data-mini]').forEach(b=>{b.disabled=true;b.classList.toggle('right',Number(b.dataset.mini)===l.q.a);if(Number(b.dataset.mini)===n&&n!==l.q.a)b.classList.add('wrong')});$('#miniFeedback').innerHTML=`<div class="feedback ${n===l.q.a?'':'bad'}"><strong>${n===l.q.a?'✓ Acertou!':'✕ Quase! A resposta é '+esc(l.q.opts[l.q.a])+'.'}</strong><br>${esc(l.q.why)}</div>`}
function handleClick(e){const go=e.target.closest('[data-open],[data-page]');if(go){const t=go.dataset.open||go.dataset.page;if(t){navigateNav(t);return}}
const mark=e.target.closest('[data-mark]');if(mark){const id=mark.dataset.mark;state.done=state.done.includes(id)?state.done.filter(x=>x!==id):[...state.done,id];save();render();return}
const nextLesson=e.target.closest('[data-next-lesson]');if(nextLesson){const i=L.findIndex(x=>x.id===nextLesson.dataset.nextLesson);navTo(`lesson/${L[(i+1)%L.length].id}`);return}
const mini=e.target.closest('[data-mini]');if(mini){answerMini(mini);return}
const examA=e.target.closest('[data-exam-answer]');if(examA&&exam&&!exam.finished){exam.answers[exam.idx]=Number(examA.dataset.examAnswer);render();return}
const start=e.target.closest('[data-start-exam]');if(start){startExam(Number(start.dataset.startExam));return}
const h=e.target.closest('[data-hormone]');if(h&&!hAnswered){const given=Number(h.dataset.hormone),correct=HORMONE_GAME[hIndex].a;hAnswered=true;if(given===correct)hScore++;$$('[data-hormone]').forEach(b=>{b.disabled=true;b.classList.toggle('right',Number(b.dataset.hormone)===correct);if(Number(b.dataset.hormone)===given&&given!==correct)b.classList.add('wrong')});$('#hFeedback').innerHTML=`<div class="feedback ${given===correct?'':'bad'}"><strong>${given===correct?'✓ Certo!':'✕ A resposta certa é: '+esc(HORMONE_GAME[hIndex].o[correct])}</strong><br>${esc(HORMONE_GAME[hIndex].e)}</div>`;$('#nextHormone').disabled=false;return}
const series=e.target.closest('[data-series]');if(series){const key=series.dataset.series;visibleSeries.has(key)?visibleSeries.delete(key):visibleSeries.add(key);$('#chart').innerHTML=chartSvg();series.classList.toggle('inactive',!visibleSeries.has(key));return}
const ref=e.target.closest('[data-reflex]');if(ref){reflexIndex=Number(ref.dataset.reflex);render();return}
const refNav=e.target.closest('[data-reflex-nav]');if(refNav){reflexIndex=refNav.dataset.reflexNav==='next'?(reflexIndex+1)%5:Math.max(0,reflexIndex-1);render();return}
if(e.target.closest('#flashCard,#flipCard')){flipFlash();return}
if(e.target.closest('#nextCard')){flashChange(1);return}
if(e.target.closest('#prevCard')){flashChange(-1);return}
if(e.target.closest('#markKnow')){markFlash('know');return}
if(e.target.closest('#markAgain')){markFlash('again');return}
if(e.target.closest('#shuffleCards')){flashOrder=rand(getDeck()).map(c=>c.id);flashIdx=0;flashFlipped=false;render();return} if(e.target.closest('#reviewCards')){setFlashFilter('review');return} if(e.target.closest('#showAllCards')){setFlashFilter('all');return}
if(e.target.closest('#nextExam')&&exam){if(exam.answers[exam.idx]===undefined)return;if(exam.idx===exam.qs.length-1){exam.finished=true;let hits=exam.qs.filter((q,i)=>exam.answers[i]===q.a).length;state.best=Math.max(state.best,Math.round(hits/exam.qs.length*100));save()}else exam.idx++;render();return}
if(e.target.closest('#prevExam')&&exam){exam.idx=Math.max(0,exam.idx-1);render();return}
if(e.target.closest('#clearExam')){exam=null;render();return}
if(e.target.closest('#nextHormone')){hIndex=(hIndex+1)%HORMONE_GAME.length;if(hIndex===0)hScore=0;hAnswered=false;render();return}
}
function updateCycleDay(d){cycleDay=+d;const phase=phaseFor(cycleDay);$('#cycleNum').textContent=cycleDay;$('#phaseName').textContent=phase[0];$('#phaseDesc').textContent=phase[1];$('#chart').innerHTML=chartSvg()}
function filterHome(s){if(!['home','aulas'].includes(curPage))navTo('aulas');const grid=$('#lessonGrid');if(!grid)return;const term=s.toLocaleLowerCase('pt-BR').normalize('NFD').replace(/[\u0300-\u036f]/g,'');const found=L.filter(l=>[l.title,l.subtitle,l.tag,l.macete].some(v=>v.toLocaleLowerCase('pt-BR').normalize('NFD').replace(/[\u0300-\u036f]/g,'').includes(term)));grid.innerHTML=found.length?found.map(lessonCard).join(''):'<div class="empty">Nenhum assunto encontrado. Tenta outra palavra.</div>'}
function applyTheme(){}
document.addEventListener('click',handleClick);
document.addEventListener('change',e=>{if(e.target.id==='flashFilter')setFlashFilter(e.target.value)});
document.addEventListener('input',e=>{if(e.target.id==='daySlider')updateCycleDay(e.target.value);if(e.target.id==='searchInput')filterHome(e.target.value)});



document.addEventListener('keydown',e=>{if(curPage==='flash'&&e.target.tagName!=='INPUT'&&e.target.tagName!=='SELECT'){if(e.key==='ArrowRight')flashChange(1);if(e.key==='ArrowLeft')flashChange(-1);if(e.key===' '&&e.target.tagName!=='BUTTON'){e.preventDefault();flipFlash()}}});
window.addEventListener('hashchange',()=>{render();window.scrollTo({top:0,behavior:'instant'})});
const shell=EstudaLabShell.mount({subject:'biologia',title:'Biologia',contentId:'subject-content',items:[{id:'home',label:'Visão geral'},{id:'aulas',label:'Aulas'},{id:'flash',label:'Flashcards'},{id:'exam',label:'Simulados'},{id:'cycle',label:'Ciclo menstrual'},{id:'hormones',label:'Jogo dos hormônios'},{id:'reflex',label:'Ato reflexo'}],navigate:navigateNav});
if(!location.hash)history.replaceState(null,'','#/home');render();
